<?php
declare(strict_types=1);
namespace MerchantDuo\CloudflareApo\Model\Build;
use MerchantDuo\CloudflareApo\Api\BuildServiceInterface;
use MerchantDuo\CloudflareApo\Model\Support\CanonicalJson;
use Magento\Framework\Filesystem\DirectoryList;
use Magento\Framework\Filesystem\Driver\File;
final class BuildService implements BuildServiceInterface {
 public function __construct(private ProjectConfigFactory $configFactory, private CanonicalJson $json, private DirectoryList $directories, private File $files) {}
 /** Generate a data-only module in an isolated var workspace; no web request invokes Node. */
 public function build(int $websiteId = 0): array { $config=$this->configFactory->create($websiteId); $canonical=$this->json->encode($config); $hash=hash('sha256',$canonical); $path=$this->directories->getPath(DirectoryList::VAR_DIR).'/merchantduo-cloudflare-apo/'.$hash; $this->files->createDirectory($path.'/src/generated'); $typescript="/** Generated by Magento. Do not edit. */\nexport const projectConfig = ".$canonical." as const;\n"; $this->files->filePutContents($path.'/src/generated/project-config.ts',$typescript); $report=['buildHash'=>$hash,'configHash'=>$hash,'workspace'=>$path,'projectConfig'=>$config,'createdAt'=>gmdate(DATE_ATOM),'validation'=>['dataOnly'=>true,'workerCore'=>'module package must supply a prebuilt Worker bundle']]; $this->files->filePutContents($path.'/build-report.json',$this->json->encode($report)); return $report; }
}
